/* ================= Audio (WebAudio, no files) ================= */
let AC=null;let soundOn=true;
function tone(f,dur=0.12,type="sine",gain=0.12,when=0){
  if(!soundOn)return;
  try{
    AC=AC||new (window.AudioContext||window.webkitAudioContext)();
    const t=AC.currentTime+when;
    const o=AC.createOscillator(),g=AC.createGain();
    o.type=type;o.frequency.setValueAtTime(f,t);
    g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(gain,t+0.015);g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
    o.connect(g).connect(AC.destination);o.start(t);o.stop(t+dur+0.02);
  }catch(e){}
}
const sfx={
  place(){tone(320,.14,"triangle",.14);tone(520,.18,"sine",.1,.05);},
  flip(){tone(660,.09,"sine",.07);tone(880,.1,"sine",.06,.06);},
  bad(){tone(140,.2,"sawtooth",.07);},
  win(){[523,659,784,1046].forEach((f,i)=>tone(f,.28,"sine",.1,i*.13));},
  pass(){tone(240,.2,"sine",.09);}
};

/* ================= State + DOM ================= */
const $=id=>document.getElementById(id);
const boardEl=$("board"),fx=$("fx"),fctx=fx.getContext("2d");
let board=startBoard(),turn="B",history=[],validCache=[],lastMove=null,gameOver=false;
let mode="ai-black",diff="medium",showHints=true,fxOn=true,aiBusy=false;
const QUOTES=["“Surround, seduce, reverse.” — Atelier note nº 3","“Corners are gold. Edges are silver.”","“Don't count discs. Count futures.”","“The quiet move is often the loudest.”","“Every flip is a small betrayal — beautiful.”"];

function buildCoords(){
  $("rowCoords").innerHTML=[1,2,3,4,5,6,7,8].map(n=>`<div>${n}</div>`).join("");
  $("colCoords").innerHTML=FILES.split("").map(f=>`<div>${f}</div>`).join("");
}
function moveName(r,c){return FILES[c]+(r+1);}
function setStatus(t){$("status").textContent=t;}
function updateMeta(){
  const{B,W,empty}=countDiscs(board);
  $("countB").textContent=B;$("countW").textContent=W;
  $("discCountMeta").textContent=`${64-empty} / 64`;
  $("moveNoMeta").textContent=String(history.length+1).padStart(2,"0");
  $("validMeta").textContent=validCache.length;
  const tot=Math.max(1,B+W);
  $("meterB").style.width=(B/tot*100)+"%";$("meterW").style.width=(W/tot*100)+"%";
  $("turnDisc").className="turn-disc "+(turn==="B"?"b":"w");
  $("labelBlack").textContent=mode==="ai-white"?"ENGINE · BLACK":mode==="2p"?"PLAYER 1 · BLACK":"YOU · BLACK";
  $("labelWhite").textContent=mode==="ai-black"?"ENGINE · WHITE":mode==="2p"?"PLAYER 2 · WHITE":"YOU · WHITE";
}
function renderMoves(){
  const el=$("moves");
  if(!history.length){el.innerHTML=`<span class="mv">— no strokes yet —</span>`;}
  else el.innerHTML=history.map((h,i)=>`<span class="mv ${h.p.toLowerCase()}">${String(i+1).padStart(2,"0")} ${h.p}·${moveName(h.r,h.c)}</span>`).join("");
  $("mvCount").textContent="· "+history.length;
  el.scrollTop=el.scrollHeight;
}
function render(){
  validCache=gameOver?[]:validMoves(board,turn);
  boardEl.innerHTML="";
  const vset=new Set(validCache.map(m=>m.r+","+m.c));
  for(let r=0;r<8;r++)for(let c=0;c<8;c++){
    const d=document.createElement("div");
    d.className="cell"+(lastMove&&lastMove.r===r&&lastMove.c===c?" last":"")+(showHints&&vset.has(r+","+c)?" valid":"");
    d.dataset.r=r;d.dataset.c=c;
    const v=board[r][c];
    if(v){const disc=document.createElement("div");disc.className="disc "+(v==="B"?"black":"white");d.appendChild(disc);}
    else if(showHints&&vset.has(r+","+c)){
      const m=validCache.find(x=>x.r===r&&x.c===c);
      const h=document.createElement("div");h.className="hint"+(m&&m.flips.length>=3?" capture":"");d.appendChild(h);
    }
    d.addEventListener("click",()=>onCell(r,c,d));
    boardEl.appendChild(d);
  }
  updateMeta();renderMoves();sizeFx();
}
function sizeFx(){const r=boardEl.getBoundingClientRect();fx.width=r.width;fx.height=r.height;fx.style.width="100%";fx.style.height="100%";}

/* particles */
let parts=[];
function burst(clientX,clientY,n=26,colors=["#c9a96a","#ece7dd","#c96f4a","#9db89a"]){
  if(!fxOn)return;
  const rect=fx.getBoundingClientRect();
  const x=clientX-rect.left,y=clientY-rect.top;
  const scale=fx.width/Math.max(1,rect.width);
  for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,sp=(1+Math.random()*4)*scale;
    parts.push({x:x*scale,y:y*scale,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp-1,life:1,decay:.015+Math.random()*.02,r:(1.5+Math.random()*2.5)*scale,c:colors[i%colors.length]});}
}
function tickFx(){
  fctx.clearRect(0,0,fx.width,fx.height);
  parts=parts.filter(p=>p.life>0);
  for(const p of parts){p.x+=p.vx;p.y+=p.vy;p.vy+=.06;p.life-=p.decay;
    fctx.globalAlpha=Math.max(0,p.life);fctx.fillStyle=p.c;fctx.beginPath();fctx.arc(p.x,p.y,p.r,0,7);fctx.fill();}
  fctx.globalAlpha=1;
  requestAnimationFrame(tickFx);
}

/* ================= Game flow ================= */
function aiToMove(){
  if(mode==="2p")return false;
  if(mode==="ai-black"&&turn==="W")return true;
  if(mode==="ai-white"&&turn==="B")return true;
  return false;
}
function onCell(r,c,cellEl){
  if(gameOver||aiBusy)return;
  if(aiToMove())return;
  const flips=flipsFor(board,r,c,turn);
  if(!flips.length){sfx.bad();cellEl.animate([{transform:"translateX(0)"},{transform:"translateX(-5px)"},{transform:"translateX(5px)"},{transform:"translateX(0)"}],{duration:220});setStatus(`${moveName(r,c)} is not a legal stroke — you must outflank.`);return;}
  doMove(r,c,turn,true);
}
function doMove(r,c,player,animate){
  const flips=applyMove(board,r,c,player);
  if(!flips)return;
  history.push({r,c,p:player,flips:flips.map(f=>f.slice())});
  lastMove={r,c};sfx.place();
  render();
  // flip animation + particles at flipped discs
  const cells=boardEl.children;
  flips.forEach(([fr,fc],i)=>{
    const cell=cells[fr*8+fc];const disc=cell&&cell.querySelector(".disc");
    if(disc){disc.classList.add("flipping");
      setTimeout(()=>{disc.className="disc "+(player==="B"?"black":"white")+" placed";if(i%2===0)sfx.flip();},140+i*28);}
  });
  if(animate){
    const rc=boardEl.children[r*8+c].getBoundingClientRect();
    burst(rc.left+rc.width/2,rc.top+rc.height/2,30);
  }
  setStatus(`${player==="B"?"Noir":"Blanc"} paints ${moveName(r,c)}, turning ${flips.length} disc${flips.length>1?"s":""}.`);
  $("quote").textContent=QUOTES[Math.floor(Math.random()*QUOTES.length)];
  setTimeout(()=>advance(player),620);
}
function advance(justMoved){
  if(gameOver)return;
  turn=opp(justMoved);
  let mv=validMoves(board,turn);
  if(!mv.length){
    const other=validMoves(board,opp(turn));
    if(!other.length)return endGame();
    sfx.pass();
    setStatus(`${turn==="B"?"Noir":"Blanc"} has no stroke — pass. ${opp(turn)==="B"?"Noir":"Blanc"} paints again.`);
    turn=opp(turn);
  }
  render();
  if(aiToMove())aiPlay();
}
function aiPlay(){
  aiBusy=true;$("thinking").style.display="inline-flex";
  $("enginePill").textContent="Engine thinking…";
  $("turnText").textContent=(turn==="B"?"Noir":"Blanc")+" is dreaming";
  setTimeout(()=>{
    const m=engineMove(board,turn,diff);
    aiBusy=false;$("thinking").style.display="none";$("enginePill").textContent="Engine ready";
    if(!m){advance(opp(turn));return;}
    $("turnText").textContent=turn==="B"?"Noir to move":"Blanc to move";
    doMove(m.r,m.c,turn,true);
  },420+Math.random()*500);
}
function endGame(){
  gameOver=true;render();
  const{B,W}=countDiscs(board);
  let title,sub;
  if(B===W){title=`A perfect <em>tie.</em>`;sub=`Noir ${B} — Blanc ${W} · the canvas is balanced.`;}
  else if(B>W){title=`Noir <em>prevails.</em>`;sub=`Noir ${B} — Blanc ${W} · darkness, elegantly.`;}
  else{title=`Blanc <em>ascends.</em>`;sub=`Noir ${B} — Blanc ${W} · light takes the gallery.`;}
  $("winTitle").innerHTML=title;$("winSub").textContent=sub;
  $("finalB").textContent=B;$("finalW").textContent=W;
  setStatus(B===W?`Tied at ${B}–${W}. A shared canvas.`:`${B>W?"Noir":"Blanc"} wins ${Math.max(B,W)}–${Math.min(B,W)}.`);
  sfx.win();$("modal").classList.add("show");
  // celebratory rain
  for(let i=0;i<6;i++)setTimeout(()=>burst(innerWidth/2+(Math.random()-.5)*400,innerHeight*0.3,40),i*180);
}
function newGame(){
  const f=$("selFirst").value;
  board=startBoard();turn=f;history=[];lastMove=null;gameOver=false;aiBusy=false;
  $("modal").classList.remove("show");
  $("turnText").textContent=turn==="B"?"Noir to move":"Blanc to move";
  setStatus(turn==="B"?"Noir opens the exhibition. Four discs on the canvas.":"Blanc opens — a rare, luminous beginning.");
  render();
  if(aiToMove())aiPlay();
}
function undo(){
  if(aiBusy)return;
  if(!history.length)return;
  const steps=(mode==="2p")?1:2;
  for(let i=0;i<steps&&history.length;i++){
    const h=history.pop();
    board[h.r][h.c]=null;
    for(const[fr,fc]of h.flips)board[fr][fc]=opp(h.p);
  }
  turn=history.length?(opp(history[history.length-1].p)===turn?turn:opp(history[history.length-1].p)): $("selFirst").value;
  // recompute turn properly: alternate from last history
  if(history.length){turn=opp(history[history.length-1].p);}else{turn=$("selFirst").value;}
  // if it's AI turn after undo, step back one more so human moves
  if(aiToMove()&&history.length){const h=history.pop();board[h.r][h.c]=null;for(const[fr,fc]of h.flips)board[fr][fc]=opp(h.p);turn=opp(history.length?history[history.length-1].p:$("selFirst")==="B"?"W":"B");if(!history.length)turn=$("selFirst").value;else turn=opp(history[history.length-1].p);}
  lastMove=history.length?{r:history[history.length-1].r,c:history[history.length-1].c}:null;
  gameOver=false;$("modal").classList.remove("show");
  $("turnText").textContent=turn==="B"?"Noir to move":"Blanc to move";
  setStatus("A stroke undone — the canvas forgives.");render();
}

/* ================= wiring ================= */
$("segMode").addEventListener("click",e=>{
  const b=e.target.closest("button");if(!b)return;
  document.querySelectorAll("#segMode button").forEach(x=>x.classList.remove("on"));
  b.classList.add("on");mode=b.dataset.mode;newGame();
});
$("selDiff").addEventListener("change",e=>diff=e.target.value);
$("selFirst").addEventListener("change",()=>newGame());
$("btnNew").addEventListener("click",newGame);
$("btnAgain").addEventListener("click",newGame);
$("btnClose").addEventListener("click",()=>$("modal").classList.remove("show"));
$("btnUndo").addEventListener("click",undo);
$("btnPass").addEventListener("click",()=>{
  if(gameOver||aiBusy||aiToMove())return;
