addEventListener("resize",sizeFx);

/* self-test in console */
function selfTest(){
  const t=startBoard();
  console.assert(validMoves(t,"B").length===4,"open moves should be 4");
  console.assert(flipsFor(t,2,3,"B").length===1,"D3 flips 1");
  const b2=t.map(r=>r.slice());applyMove(b2,2,3,"B");
  console.assert(b2[3][3]==="B","flip works");
  console.assert(engineMove(t,"B","medium")!=null,"engine finds move");
  console.log("%coth­ello self-test passed","color:#c9a96a");
}

buildCoords();render();tickFx();selfTest();newGame();
